CREATE TABLE teacher_payment_batches(id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER NOT NULL REFERENCES teacher_payments(id),teacher_id INTEGER NOT NULL REFERENCES teachers(id),student_id INTEGER NOT NULL REFERENCES students(id),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),hours_micros INTEGER NOT NULL CHECK(hours_micros>0),mode TEXT NOT NULL CHECK(mode IN('New','Existing')),reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE teacher_hour_allocations(id INTEGER PRIMARY KEY AUTOINCREMENT,batch_id INTEGER NOT NULL REFERENCES teacher_payment_batches(id),lesson_id INTEGER NOT NULL REFERENCES lessons(id),hours_micros INTEGER NOT NULL CHECK(hours_micros>0),amount INTEGER NOT NULL CHECK(amount>0));
CREATE INDEX teacher_hour_lesson ON teacher_hour_allocations(lesson_id);
CREATE TRIGGER teacher_hours_immutable_update BEFORE UPDATE ON teacher_hour_allocations BEGIN SELECT RAISE(ABORT,'Paid lesson allocations are immutable'); END;
CREATE TRIGGER teacher_hours_immutable_delete BEFORE DELETE ON teacher_hour_allocations BEGIN SELECT RAISE(ABORT,'Paid lesson allocations cannot be deleted'); END;
CREATE TRIGGER teacher_batch_immutable_update BEFORE UPDATE ON teacher_payment_batches BEGIN SELECT RAISE(ABORT,'Teacher payment batches are immutable'); END;
CREATE TRIGGER teacher_batch_immutable_delete BEFORE DELETE ON teacher_payment_batches BEGIN SELECT RAISE(ABORT,'Teacher payment batches cannot be deleted'); END;
CREATE TRIGGER teacher_batch_lesson_guard BEFORE UPDATE ON lessons WHEN EXISTS(SELECT 1 FROM teacher_hour_allocations WHERE lesson_id=OLD.id) AND (NEW.t IS NOT OLD.t OR NEW.s IS NOT OLD.s OR NEW.sub IS NOT OLD.sub OR NEW.st IS NOT OLD.st OR NEW.date IS NOT OLD.date OR NEW.d IS NOT OLD.d OR NEW.tr IS NOT OLD.tr OR NEW.tc IS NOT OLD.tc OR NEW.oc IS NOT OLD.oc OR NEW.bcost IS NOT OLD.bcost OR NEW.trx IS NOT OLD.trx OR NEW.bc IS NOT OLD.bc) BEGIN SELECT RAISE(ABORT,'A paid lesson must retain its teacher, student, hours and saved cost'); END;
CREATE TRIGGER teacher_batch_tp_guard BEFORE UPDATE ON teacher_payments WHEN (EXISTS(SELECT 1 FROM teacher_payment_batches WHERE payment_id=OLD.id) OR (OLD.src='Live' AND EXISTS(SELECT 1 FROM teacher_hour_allocations WHERE lesson_id=OLD.lk))) AND (NEW.p IS NOT OLD.p OR NEW.date IS NOT OLD.date OR NEW.cur IS NOT OLD.cur OR NEW.amt IS NOT OLD.amt OR NEW.rx IS NOT OLD.rx OR NEW.bamt IS NOT OLD.bamt OR NEW.bc IS NOT OLD.bc OR NEW.src IS NOT OLD.src OR NEW.lk IS NOT OLD.lk) BEGIN SELECT RAISE(ABORT,'A batched teacher payment is immutable'); END;
